# Description: Bayesian Optimization class using BoTorch and GPyTorch for optimization
# Code:
```python
import numpy as np
import torch
from torch import optim
from botorch.core import acquisition, kernels, models
from botorch.utils import get_hessian
from botorch.acquisition import qExpectedImprovement, qLogExpectedImprovement, qNoisyExpectedImprovement, qUpperConfidenceBound
from gpytorch.models import ExactGPR
from gpytorch.acquisition import Acquisition

class Optimize_with_BO:
    def __init__(self, budget: int, dim: int, initial_points: int = 10, random_seed: int = 42, acq_func='EI'):
        self.budget = budget
        self.dim = dim
        self.initial_points = initial_points
        self.random_seed = random_seed
        self.model = ExactGPR(dim=self.dim)
        self.acq = self._get_acq_func(acq_func)
        self.optimizer = optim.Adam(self.model.parameters(), lr=0.01)
        self.x_doe = self.generate_initial_doe()

    def generate_initial_doe(self):
        np.random.seed(self.random_seed)
        x_doe = []
        for i in range(self.initial_points):
            x = np.random.uniform(-5, 5, self.dim)
            x_doe.append(x)
        return torch.tensor(x_doe, dtype=torch.float32)

    def _get_acq_func(self, acq_func):
        if acq_func == 'EI':
            return qExpectedImprovement(self.model, self.model.acq_function)
        elif acq_func == 'LI':
            return qLogExpectedImprovement(self.model, self.model.acq_function)
        elif acq_func == 'NEI':
            return qNoisyExpectedImprovement(self.model, self.model.acq_function)
        elif acq_func == 'UB':
            return qUpperConfidenceBound(self.model, self.model.acq_function)
        else:
            raise ValueError('Invalid acquisition function')

    def __call__(self, func):
        for i in range(self.budget):
            x_doe = self.x_doe + torch.randn(self.initial_points, self.dim, device='cuda')
            self.x_doe = x_doe.detach()
            y_doe = func(torch.tensor(x_doe, dtype=torch.float32))

            self.model.fit(self.x_doe, y_doe, self.optimizer)

            z = self.model.predict(torch.tensor(self.x_doe, dtype=torch.float32), self.model.aux_acq_function)
            best_x = self.acq(z, torch.tensor([0.0, 0.0], dtype=torch.float32))

            x = best_x + torch.randn(best_x.shape[0], self.dim, device='cuda')
            f = func(x)
            if f < self.model.f_min:
                self.model.f_min = f
                self.model.f_min_x = x

            self.x_doe = self.x_doe.detach()
        return self.model.f_min, self.model.f_min_x
```

In this refined version, the selected acquisition function is the `qExpectedImprovement` (EI) by default. However, you can specify the desired acquisition function by passing it as a string argument to the `__init__` method, such as `'LI'` for `qLogExpectedImprovement`, `'NEI'` for `qNoisyExpectedImprovement`, or `'UB'` for `qUpperConfidenceBound`.
